select setval('public.trip_code_seq', greatest((select coalesce(max(substring(trip_code from '([0-9]+)$')::bigint), 100) from public.truck_trips), (select last_value from public.trip_code_seq)));
select setval('public.order_code_seq', greatest((select coalesce(max(substring(order_code from '([0-9]+)$')::bigint), 100) from public.customer_orders), (select last_value from public.order_code_seq)));
select setval('public.purchase_code_seq', greatest((select coalesce(max(substring(purchase_code from '([0-9]+)$')::bigint), 100) from public.purchases), (select last_value from public.purchase_code_seq)));
select setval('public.payment_code_seq', greatest((select coalesce(max(substring(payment_code from '([0-9]+)$')::bigint), 100) from public.payments), (select last_value from public.payment_code_seq)));

commit;
